<div class="d-flex justify-content-between align-items-center content-heading mb-4"><div><h1>Customers</h1><p>Manage customer profiles that will be used by the live ecommerce store.</p></div><a href="<?php echo e(route('admin.customers.create')); ?>" class="btn text-white" style="background:var(--brand)"><i class="bi bi-person-plus me-1"></i>Add customer</a></div><div class="panel p-0 overflow-hidden"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Customer</th><th>Phone</th><th>Email</th><th>Gender</th><th>Status</th><th>Joined</th><th class="text-end">Action</th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $customers; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $customer): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td><div class="d-flex align-items-center gap-2"><?php if($customer->profileMedia): ?><img class="product-list-image rounded-circle" src="<?php echo e($customer->profileMedia->url); ?>" alt="<?php echo e($customer->full_name); ?>"><?php else: ?><div class="customer-avatar"><?php echo e(strtoupper(substr($customer->first_name,0,1))); ?></div><?php endif; ?><div><div class="fw-semibold"><?php echo e($customer->full_name); ?></div><?php if($customer->date_of_birth): ?><small class="text-muted">Born <?php echo e($customer->date_of_birth->format('d M Y')); ?></small><?php endif; ?></div></div></td><td><?php echo e($customer->phone); ?></td><td><?php echo e($customer->email ?: '—'); ?></td><td class="text-capitalize"><?php echo e($customer->gender ?: '—'); ?></td><td><span class="order-status <?php echo e($customer->is_active ? 'delivered' : 'cancelled'); ?>"><?php echo e($customer->is_active ? 'Active' : 'Inactive'); ?></span></td><td><?php echo e($customer->created_at->format('d M Y')); ?></td><td class="text-end"><a href="<?php echo e(route('admin.customers.edit',$customer)); ?>" class="action-button edit"><i class="bi bi-pencil-square me-1"></i>Edit</a><form class="d-inline" method="POST" action="<?php echo e(route('admin.customers.destroy',$customer)); ?>" onsubmit="return confirm('Delete this customer?')"><?php echo csrf_field(); ?> <?php echo method_field('DELETE'); ?><button class="action-button delete"><i class="bi bi-trash3 me-1"></i>Delete</button></form></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="7" class="py-5 text-center text-muted"><i class="bi bi-people fs-2 d-block mb-2"></i>No customers yet.</td></tr><?php endif; ?></tbody></table></div></div><div class="mt-3"><?php echo e($customers->links()); ?></div>
